def build_result(stages):
    order = ['SUCCESS', 'UNSTABLE', 'FAILURE']
    result = 'SUCCESS'
    ran = []
    for st in stages:
        ran.append(st['name'])
        if st['status'] == 'aborted':
            return 'ABORTED', ran
        if st['status'] == 'error':
            return 'FAILURE', ran
        if st.get('tests_failed', 0) > 0 and order.index(result) < order.index('UNSTABLE'):
            result = 'UNSTABLE'
    return result, ran
